export type Zone = {
  id: string;
  name: string;
  area: string;
  price: number;
  freeFrom: number;
  minOrder: number;
  time: string;
  express: string;
  currency: string;
};

export type ZoneLabels = {
  caption: string;
  zone: string;
  price: string;
  freeFrom: string;
  minOrder: string;
  time: string;
  express: string;
};
